from 写入第二遍 import add
add('06_001',10,'16:9，青正面头肩近景居画面右侧，左侧留她抬起的手与扣腕的另一只手；轻移半步把手指与半垂双眼同时放在清晰面内。','青慢慢睁开眼，半垂的眼睑压住思绪；她以一手扣住另一手腕，抬起的手指依次张开又弯回，腕部发出两下短促轻响。想到失去意识的后果，她牙关微露，指节短颤一下；想到村民，她目光从手上移向城内房屋的画外方向，扣腕的手却仍没松。','两侧头发与指缝之间露出蓝灰云天和淡灰云层，低处薄尘退成一条软边。','云天冷白光从正上方散开，手背、脸颊各有软亮面，指缝灰影清楚。','两下轻小关节响，指尖牵动护腕的布料细声，呼吸仍略急。',ja=['意識を失う前に倒せなかったら、全部おしまいだ。','私が倒れた後も、村の人たちを守ってくれる誰かが必要…'],tone='内心第一句沉重清楚，第二句由急转缓，把所需的人想具体，尾句带未找到答案的迟疑。',kind='mixed',phase='state',node={'青.判断':'考虑招式后失去意识的风险，尚未发动'},meaning='扣腕、张指、半垂眼与保护村民的内心台词并行。',characters=['青'],card={'opening':'青在自己承受后果与村民安危之间权衡。','beats':['睁眼扣腕，指节动两下','想到昏倒时指节短颤','想到村民时抬视线寻找接替者'],'coupling':'手部试动承载发招冲动，视线移开表达责任牵引。','landing':'手仍扣住腕，答案还没有到。'})
add('06_002',2,'16:9，青半张脸的近景偏在画面右侧，左侧大块蓝灰天空留给画外声音方向；固定机位，眉眼由半垂升为圆睁。','一个女声从青身侧传来。青先停住指尖，眼睛骤然睁大，嘴松成小圆口；视线先越向声源，头晚一小拍跟过去，肩膀仍朝着武士原来的方向。','画面左侧留蓝灰云天，身后低层米灰薄尘在平台外缘漂移。','上方冷白柔光保持，眼中冷白反光随转视线挪向一边。','风声中传来近处鞋跟的一点石面轻点，青吸气半口。',ja=['ここにいたのね。'],tone='董白从画外平直地招呼，带找到人的笃定。',kind='mixed',phase='process',meaning='董白先在画外出声，青惊讶转向而未见董白全貌。',characters=['青','董白'],card={'opening':'寻找接替者的念头被女声打断。','beats':['指尖停、眼睛骤睁','先转视线，再带头转向声源'],'coupling':'突来的声音直接触发惊愕，与前镜沉思形成转折。','landing':'青把希望投向尚未看清的人。'})
add('06_003',2,'16:9，青侧脸特写居画面左侧，视线与喊声方向指向右侧空隙；以她转头为轴短移，停在耳尖、圆眼和张口同框的角度。','青把头彻底转向女声，眼睛圆睁，嘴骤然张开；她脱口喊出春子的名字，胸口随吸气抬起，身体也朝声源轻倾半步。长发比转头晚一拍扫过耳后，喊完嘴仍张着，等着对方回应。','右侧空隙是蓝灰天空与层叠浅灰云，青肩后下缘一层米灰烟尘。','正上方冷白柔光让耳缘和脸颊清楚，发内保持冷灰层次。','急转带出的发丝擦声，短促吸气接衣料轻牵。',ja=['春子姉さん？！'],tone='惊喜先冲出口，疑问在句尾抬起，尚未核实来人。',kind='mixed',phase='process',meaning='青听声误喊春子姐姐，误认台词与急转侧脸保留。',characters=['青'],card={'opening':'青把听见的声音误当成期待的支援。','beats':['转头张口，身体微倾','喊完仍张口等待'],'coupling':'希望先于识别产生，发声紧随转头。','landing':'误认等待下一镜纠正。'})
